begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.id(n integer)returns uuid language sql immutable as $$select('ae310000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.claim(n integer)returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'session_id',pg_temp.id(n+10),'role','authenticated','user_metadata',jsonb_build_object('admin',true,'payment_verified',true))::text,true)$$;
insert into auth.users(id,email,email_confirmed_at)select pg_temp.id(n),'synthetic-manual-'||n||'@example.test',now()from generate_series(1,4)n;
insert into auth.sessions(id,user_id)select pg_temp.id(n+10),pg_temp.id(n)from generate_series(1,4)n;
insert into public.doctor_candidate_admissions(id,user_id,purpose,evidence_ref,valid_until)select pg_temp.id(n+20),pg_temp.id(n),'synthetic_fixture','disposable-manual:'||n,clock_timestamp()+interval'2 hours'from generate_series(1,4)n;
insert into public.doctor_profiles(user_id,display_name)values(pg_temp.id(1),'Synthetic owner A'),(pg_temp.id(2),'Synthetic owner B');
insert into public.practices(id,owner_user_id,name)values(pg_temp.id(31),pg_temp.id(1),'Synthetic manual A'),(pg_temp.id(32),pg_temp.id(2),'Synthetic manual B');
insert into public.memberships(id,practice_id,user_id,capabilities)values(pg_temp.id(33),pg_temp.id(31),pg_temp.id(3),array['patients.read']);
update public.doctor_edition_policy set mode='administrative_candidate',revision=revision+1,change_reason='Owned synthetic manual cases';
insert into public.doctor_saas_terms_versions(id,plan_key,version,status,currency,currency_exponent,monthly_minor,yearly_minor,trial_days,staff_limit,staff_unlimited,clinic_limit,clinic_unlimited,over_limit_policy,renewal_policy,grace_days,expiry_policy,cancellation_policy,refund_policy,terms_document_ref,commercial_approval_ref,legal_approval_ref)
 values(pg_temp.id(51),'synthetic-manual',1,'approved','EGP',2,19900,199000,0,4,false,1,false,'block_new_allocation','manual',0,'historical_read_only','period_end','manual_review','synthetic-manual/v1','SYNTHETIC_ONLY','SYNTHETIC_ONLY');
update public.doctor_saas_configuration set terms_version_id=pg_temp.id(51),revision=revision+1,change_reason='Synthetic terms only';
insert into public.doctor_saas_terms_documents(terms_version_id,document_ref,content_en,content_ar)values(pg_temp.id(51),'synthetic-manual/v1','Synthetic fixture; no live merchant or legal approval.','اختبار اصطناعي فقط دون اعتماد تاجر أو قانون.');
create temporary table results(name text primary key,value jsonb);grant all on results to authenticated;
create temporary table moments(value timestamptz);insert into moments values(clock_timestamp());grant select on moments to authenticated;
set local role authenticated;select pg_temp.claim(1);
select is(public.doctor_manual_payment_configuration()->>'selected_route','instapay_manual','route choice is manual InstaPay');
select is(public.doctor_manual_payment_configuration()->>'configured','false','no enabled recipient seeded');
select is(public.doctor_manual_payment_configuration()->'recipient','null'::jsonb,'no invented recipient exposed');
insert into results values('quote-a',public.doctor_create_saas_quote(pg_temp.id(51),2,0,'monthly','synthetic-manual/v1',pg_temp.id(61)));
insert into results values('intent-a',public.doctor_prepare_saas_payment(((select value from results where name='quote-a')->>'quote_id')::uuid,pg_temp.id(62)));
select throws_ok($$select public.doctor_submit_manual_payment(((select value from results where name='intent-a')->>'intent_id')::uuid,'SYNTHETIC-CUSTOMER-REF',(select value from moments),1,pg_temp.id(63))$$,'DS008','DOCTOR_MANUAL_PAYMENT_UNCONFIGURED','default configuration refuses notices');
reset role;
insert into public.doctor_manual_payment_recipients(id,account_key,address_kind,address,beneficiary_name,instructions_en,instructions_ar,currency,currency_exponent,merchant_approval_ref)
 values(pg_temp.id(71),pg_temp.id(72),'ipa','synthetic-fixture-only@instapay','Synthetic fixture recipient','Do not transfer actual funds.','لا تحول أموالاً حقيقية.','EGP',2,'SYNTHETIC_FIXTURE_ONLY');
update public.doctor_manual_payment_configuration set recipient_id=pg_temp.id(71),enabled=true,acceptance_mode='synthetic',revision=revision+1,change_reason='Disposable fixture only';
insert into public.doctor_manual_payment_reviewers(user_id,enabled,revision,approval_ref,valid_until)values(pg_temp.id(4),true,1,'SYNTHETIC_REVIEWER',clock_timestamp()+interval'1 hour'),(pg_temp.id(1),true,1,'SYNTHETIC_SELF_REVIEW_DENIAL',clock_timestamp()+interval'1 hour');
set local role authenticated;select pg_temp.claim(1);
insert into results values('notice-a',public.doctor_submit_manual_payment(((select value from results where name='intent-a')->>'intent_id')::uuid,'SYNTHETIC-CUSTOMER-REF',(select value from moments),2,pg_temp.id(63)));
select is((select value->>'status'from results where name='notice-a'),'submitted','customer claim stays submitted');
select is((select value->>'automatic_verification'from results where name='notice-a'),'false','no automatic verification');
select is((select value->>'live_acceptance_enabled'from results where name='notice-a'),'false','no real payments authorized');
select is(public.doctor_submit_manual_payment(((select value from results where name='intent-a')->>'intent_id')::uuid,'SYNTHETIC-CUSTOMER-REF',(select value from moments),2,pg_temp.id(63)),(select value from results where name='notice-a'),'exact submission replay returns receipt');
select throws_ok($$select public.doctor_submit_manual_payment(((select value from results where name='intent-a')->>'intent_id')::uuid,'CHANGED',(select value from moments),2,pg_temp.id(63))$$,'22023','DOCTOR_IDEMPOTENCY_CONFLICT','same key cannot change transfer claim');
select throws_ok($$select public.doctor_review_manual_payment(((select value from results where name='notice-a')->>'id')::uuid,0,'funds_verified','self review','BANK-REF','19900','EGP',(select value from moments),'bank statement',true,pg_temp.id(64))$$,'42501','DOCTOR_INDEPENDENT_REVIEW_REQUIRED','authorized reviewer cannot verify own payment');
select pg_temp.claim(2);
select is(public.doctor_manual_payments(null,false,1)->>'total','0','other subscriber cannot see notices');
select throws_ok($$select public.doctor_manual_payments(((select value from results where name='notice-a')->>'id')::uuid,false,1)$$,'42501','DOCTOR_ACCESS_DENIED','foreign direct notice denied');
select throws_ok($$select public.doctor_manual_payments(null,true,1)$$,'42501','DOCTOR_MANUAL_REVIEW_AUTHORITY_REQUIRED','editable admin metadata grants no review access');
insert into results values('quote-b',public.doctor_create_saas_quote(pg_temp.id(51),2,0,'monthly','synthetic-manual/v1',pg_temp.id(65)));
insert into results values('intent-b',public.doctor_prepare_saas_payment(((select value from results where name='quote-b')->>'quote_id')::uuid,pg_temp.id(66)));
insert into results values('notice-b',public.doctor_submit_manual_payment(((select value from results where name='intent-b')->>'intent_id')::uuid,'SAME-CUSTOMER-COPIED-REF',(select value from moments),2,pg_temp.id(67)));
select pg_temp.claim(3);
select throws_ok($$select public.doctor_submit_manual_payment(((select value from results where name='intent-a')->>'intent_id')::uuid,'SYNTHETIC-CUSTOMER-REF',(select value from moments),2,pg_temp.id(68))$$,'42501','DOCTOR_OWNER_ENROLLMENT_REQUIRED','delegated practice permission is not subscriber authority');
select pg_temp.claim(4);
select is(public.doctor_manual_payments(null,true,1)->>'total','2','trusted independent reviewer gets Doctor-only queue');
insert into results values('under-review',public.doctor_review_manual_payment(((select value from results where name='notice-a')->>'id')::uuid,0,'under_review','Checking beneficiary account',null,null,null,null,null,false,pg_temp.id(81)));
select is((select value->>'status'from results where name='under-review'),'under_review','review start is audited');
select throws_ok($$select public.doctor_review_manual_payment(((select value from results where name='notice-a')->>'id')::uuid,0,'rejected','stale decision',null,null,null,null,null,false,pg_temp.id(82))$$,'40001','DOCTOR_MANUAL_REVIEW_CONFLICT','stale reviewer revision denied');
select throws_ok($$select public.doctor_review_manual_payment(((select value from results where name='notice-a')->>'id')::uuid,1,'funds_verified','image alone','BANK-REF','19900','EGP',(select value from moments),'customer screenshot',false,pg_temp.id(82))$$,'22023','DOCTOR_RECEIVED_FUNDS_VERIFICATION_REQUIRED','screenshot without independent bank verification denied');
select throws_ok($$select public.doctor_review_manual_payment(((select value from results where name='notice-a')->>'id')::uuid,1,'funds_verified','wrong amount','BANK-REF','19899','EGP',(select value from moments),'bank statement',true,pg_temp.id(82))$$,'22023','DOCTOR_RECEIVED_FUNDS_VERIFICATION_REQUIRED','underpayment cannot verify exact quote');
select throws_ok($$select public.doctor_review_manual_payment(((select value from results where name='notice-a')->>'id')::uuid,1,'funds_verified','wrong currency','BANK-REF','19900','USD',(select value from moments),'bank statement',true,pg_temp.id(82))$$,'22023','DOCTOR_RECEIVED_FUNDS_VERIFICATION_REQUIRED','currency mismatch cannot verify');
insert into results values('verified',public.doctor_review_manual_payment(((select value from results where name='notice-a')->>'id')::uuid,1,'funds_verified','Checked beneficiary bank record',' bank-ref ','19900','EGP',(select value from moments),'SYNTHETIC_BENEFICIARY_BANK_RECORD',true,pg_temp.id(83)));
select is((select value->>'status'from results where name='verified'),'funds_verified','verified funds recorded separately from activation');
select is(public.doctor_review_manual_payment(((select value from results where name='notice-a')->>'id')::uuid,1,'funds_verified','Checked beneficiary bank record',' bank-ref ','19900','EGP',(select value from moments),'SYNTHETIC_BENEFICIARY_BANK_RECORD',true,pg_temp.id(83)),(select value from results where name='verified'),'review replay returns exact result without duplicate funds');
select throws_ok($$select public.doctor_review_manual_payment(((select value from results where name='notice-b')->>'id')::uuid,0,'funds_verified','Duplicate bank record','BANK-REF','19900','EGP',(select value from moments),'SYNTHETIC_BANK_RECORD',true,pg_temp.id(84))$$,'23505',null,'one received bank reference cannot fund two subscriptions');
select throws_ok($$select public.doctor_review_manual_payment(((select value from results where name='notice-a')->>'id')::uuid,2,'rejected','Cannot rewrite funds history',null,null,null,null,null,false,pg_temp.id(85))$$,'22023','DOCTOR_MANUAL_REVIEW_STATE_INVALID','received funds history cannot be overwritten by rejection');
reset role;
select is((select count(*)from public.doctor_manual_received_funds),1::bigint,'one immutable independently verified funds record');
select is((select count(*)from public.doctor_saas_periods),0::bigint,'neither customer evidence nor verification alone creates entitlement');
select is((select count(*)from public.doctor_manual_payment_reviews),2::bigint,'only successful review transitions persist');
select is((select count(*)from public.doctor_manual_payment_reviewer_events),2::bigint,'review authority changes are attributed');
select throws_ok($$update public.doctor_manual_payment_notices set transfer_reference='overwritten'$$,'42501','DOCTOR_SAAS_HISTORY_IMMUTABLE','customer evidence immutable');
select throws_ok($$delete from public.doctor_manual_received_funds$$,'42501','DOCTOR_SAAS_HISTORY_IMMUTABLE','received-funds audit immutable');
update public.doctor_manual_payment_reviewers set enabled=false,revision=revision+1,approval_ref='SYNTHETIC_REVOKED'where user_id=pg_temp.id(4);
set local role authenticated;select pg_temp.claim(4);
select throws_ok($$select public.doctor_manual_payments(null,true,1)$$,'42501','DOCTOR_MANUAL_REVIEW_AUTHORITY_REQUIRED','revocation removes queue access');
select throws_ok($$select public.doctor_review_manual_payment(((select value from results where name='notice-a')->>'id')::uuid,1,'funds_verified','Checked beneficiary bank record',' bank-ref ','19900','EGP',(select value from moments),'SYNTHETIC_BENEFICIARY_BANK_RECORD',true,pg_temp.id(83))$$,'42501','DOCTOR_MANUAL_REVIEW_AUTHORITY_REQUIRED','revocation denies even successful command replay');
reset role;
select ok(not has_table_privilege(role_name,'public.'||table_name,'select,insert,update,delete,truncate'),'no raw '||role_name||' grant on '||table_name)
 from unnest(array['anon','authenticated','service_role'])role_name cross join unnest(array['doctor_manual_payment_recipients','doctor_manual_payment_configuration','doctor_manual_payment_configuration_events','doctor_manual_payment_reviewers','doctor_manual_payment_reviewer_events','doctor_manual_payment_notices','doctor_manual_received_funds','doctor_manual_payment_reviews'])table_name;
select ok((select bool_and(relrowsecurity and relforcerowsecurity)from pg_class where relname like 'doctor_manual_%'and relnamespace='public'::regnamespace),'manual tables force RLS');
select * from finish();rollback;
